${RULES}`,
      { label: `verify:${p.n}`, phase: 'Verify', schema: VERDICT_SCHEMA }
    ).then((v) => ({ review: rev, verdict: v }))
  }
)

log(`spent ~${Math.round((budget.spent() - START) / 1000)}k of ${Math.round(TARGET / 1000)}k target (this workflow)`)
